#include <bits/stdc++.h>
using namespace std;

static char rbuf[1 << 20];
static size_t rlen = 0, rpos = 0;
static inline int gc(){
    if (rpos == rlen){
        rlen = fread(rbuf, 1, sizeof(rbuf), stdin);
        rpos = 0;
        if (rlen == 0) return -1;
    }
    return (unsigned char)rbuf[rpos++];
}
static inline int rdInt(){
    int c = gc();
    while (c != -1 && (c < '0' || c > '9')) c = gc();
    int x = 0;
    while (c >= '0' && c <= '9'){ x = x * 10 + (c - '0'); c = gc(); }
    return x;
}

static char wbuf[1 << 21];
static size_t wpos = 0;
static inline void flushOut(){ if (wpos){ fwrite(wbuf, 1, wpos, stdout); wpos = 0; } }
static inline void wrIntSp(int x, char sep){
    if (wpos + 16 > sizeof(wbuf)) flushOut();
    if (x == 0){ wbuf[wpos++] = '0'; }
    else {
        char tmp[12]; int t = 0;
        while (x){ tmp[t++] = (char)('0' + x % 10); x /= 10; }
        while (t) wbuf[wpos++] = tmp[--t];
    }
    wbuf[wpos++] = sep;
}

int main(){
    int N = rdInt();
    int M = rdInt();
    const int NS = 2 * M;

    // Directed state per ordered adjacent pair (a->b)
    vector<int> DF(NS), DT(NS);
    for (int i = 0; i < M; ++i){
        int u = rdInt(), v = rdInt();
        DF[2*i]   = u; DT[2*i]   = v;
        DF[2*i+1] = v; DT[2*i+1] = u;
    }

    // Constraint is exactly: u_{i+2} > u_i and u_i ~ u_{i+1}.
    // DP over states (a->b): F(a->b) = max over c~b, c>a of (1 + F(b->c)).
    // Transition (a->b) -> (b->c) has a+b < b+c, so processing states in
    // decreasing (a+b) is a valid topological order.

    // CSR of outgoing edges per node, neighbors ascending
    vector<int> adjN(NS), adjE(NS);
    vector<int> start(N + 2, 0);
    vector<int> cnt(N + 2, 0), off(N + 2, 0);
    {
        int run = 0;
        for (int d = 0; d < NS; ++d) ++cnt[DT[d]];
        for (int v = 1; v <= N; ++v){ off[v] = run; run += cnt[v]; }
        vector<int> tA(NS), tB(NS), tD(NS);
        for (int d = 0; d < NS; ++d){
            int q = off[DT[d]]++;
            tA[q] = DF[d]; tB[q] = DT[d]; tD[q] = d;
        }
        fill(cnt.begin(), cnt.end(), 0);
        run = 0;
        for (int q = 0; q < NS; ++q) ++cnt[tA[q]];
        for (int v = 1; v <= N; ++v){ start[v] = run; run += cnt[v]; }
        start[N + 1] = run;
        for (int v = 1; v <= N; ++v) off[v] = start[v];
        for (int q = 0; q < NS; ++q){
            int r = off[tA[q]]++;
            adjN[r] = tB[q]; adjE[r] = tD[q];
        }
    }

    // Order states by s = a + b, decreasing (counting sort)
    vector<int> order(NS);
    {
        int maxS = 2 * N;
        vector<int> c2(maxS + 2, 0), o2(maxS + 2, 0);
        for (int d = 0; d < NS; ++d) ++c2[DF[d] + DT[d]];
        int run = 0;
        for (int s = maxS; s >= 0; --s){ o2[s] = run; run += c2[s]; }
        for (int d = 0; d < NS; ++d) order[o2[DF[d] + DT[d]]++] = d;
    }

    vector<int> F(NS, 0), best(N + 1, 0), ptr(N + 1, 0);
    for (int v = 1; v <= N; ++v) ptr[v] = start[v + 1] - 1;

    const int* np = adjN.data();
    const int* ep = adjE.data();

    for (int idx = 0; idx < NS; ++idx){
        int d = order[idx];
        int a = DF[d], b = DT[d];
        int p = ptr[b];
        int lo = start[b];
        int bb = best[b];
        // successors are (b->c) with c > a; for fixed b, states come with decreasing a,
        // so a monotone pointer over the sorted neighbor list keeps a running suffix max
        while (p >= lo && np[p] > a){
            int val = 1 + F[ep[p]];
            if (val > bb) bb = val;
            --p;
        }
        ptr[b] = p;
        best[b] = bb;
        F[d] = bb;
    }

    // Answer for start C: max(1, max over c~C of 2 + F(C->c))
    for (int v = 1; v <= N; ++v){
        int r = 1;
        for (int p = start[v]; p < start[v + 1]; ++p){
            int val = 2 + F[adjE[p]];
            if (val > r) r = val;
        }
        wrIntSp(r, (v == N) ? '\n' : ' ');
    }
    flushOut();
    return 0;
}
